static HFONT font(int size,int weight){return CreateFontW(-size,0,0,0,weight,0,0,0,DEFAULT_CHARSET,0,0,CLEARTYPE_QUALITY,0,L"Microsoft YaHei UI");}
static void txt(HDC dc,int x,int y,int size,int weight,COLORREF color,const wchar_t *s){HFONT f=font(size,weight),old=SelectObject(dc,f);SetTextColor(dc,color);SetBkMode(dc,TRANSPARENT);TextOutW(dc,x,y,s,(int)wcslen(s));SelectObject(dc,old);DeleteObject(f);}
static void box(HDC dc,int x,int y,int w,int h,COLORREF c){HBRUSH b=CreateSolidBrush(c);RECT r={x,y,x+w,y+h};FillRect(dc,&r,b);DeleteObject(b);}
static Schedule schedule(void){Schedule s={salary,hours,start,lunch,rest,off};return s;}
static HWND control(HWND parent,const wchar_t *cls,const wchar_t *text,DWORD style,int x,int y,int w,int h,int id){HWND c=CreateWindowExW(wcscmp(cls,L"EDIT")==0?WS_EX_CLIENTEDGE:0,cls,text,WS_CHILD|WS_VISIBLE|style,x,y,w,h,parent,(HMENU)(INT_PTR)id,GetModuleHandleW(0),0);SendMessageW(c,WM_SETFONT,(WPARAM)uiFont,TRUE);return c;}
static void card(HDC dc,int x,int y,int w,int h,COLORREF color){HBRUSH b=CreateSolidBrush(color);HPEN pen=CreatePen(PS_SOLID,1,color);HGDIOBJ ob=SelectObject(dc,b),op=SelectObject(dc,pen);RoundRect(dc,x,y,x+w,y+h,22,22);SelectObject(dc,ob);SelectObject(dc,op);DeleteObject(b);DeleteObject(pen);}
static void clipped(HDC dc,int x,int y,int width,int size,COLORREF color,const wchar_t *s){HFONT f=font(size,600),old=SelectObject(dc,f);SetTextColor(dc,color);SetBkMode(dc,TRANSPARENT);RECT r={x,y,x+width,y+40};DrawTextW(dc,s,-1,&r,DT_SINGLELINE|DT_END_ELLIPSIS|DT_NOPREFIX);SelectObject(dc,old);DeleteObject(f);}
static time_t cached_eta(void){static time_t since=-1,result;static double cost=-1;static Schedule last={0};Schedule s=schedule();if(since!=goalstart||cost!=price||last.salary!=s.salary||last.hours!=s.hours||last.start!=s.start||last.lunch!=s.lunch||last.rest!=s.rest||last.off!=s.off){result=goal_eta(goalstart,price,s);since=goalstart;cost=price;last=s;}return result;}
static void load(void){wchar_t b[64];GetPrivateProfileStringW(L"pay",L"salary",L"4500",b,64,ini);salary=wcstod(b,0);GetPrivateProfileStringW(L"pay",L"hours",L"7.5",b,64,ini);hours=wcstod(b,0);start=GetPrivateProfileIntW(L"pay",L"start",540,ini);lunch=GetPrivateProfileIntW(L"pay",L"lunch",720,ini);rest=GetPrivateProfileIntW(L"pay",L"rest",60,ini);off=GetPrivateProfileIntW(L"pay",L"off",0,ini);if(!isfinite(salary)||!isfinite(hours)||salary<=0||hours<=0||hours>16||start<0||lunch<start||rest<0||start+hours*60+rest>1440||lunch>start+hours*60||off<0||off>6){salary=4500;hours=7.5;start=540;lunch=720;rest=60;off=0;}}
static void loadgoal(void){wchar_t b[80];GetPrivateProfileStringW(L"goal",L"name",L"",wish,81,ini);GetPrivateProfileStringW(L"goal",L"price",L"0",b,80,ini);price=wcstod(b,0);GetPrivateProfileStringW(L"goal",L"since",L"0",b,80,ini);goalstart=(time_t)_wcstoi64(b,0,10);if(!isfinite(price)||price<=0||price>1000000||goalstart<=0||!wish[0]){price=0;goalstart=0;}}
static void save(void){wchar_t b[64];const wchar_t *keys[]={L"salary",L"hours",L"start",L"lunch",L"rest",L"off"};double v[]={salary,hours,start,lunch,rest,off};for(int i=0;i<6;i++){swprintf(b,64,L"%.6f",v[i]);WritePrivateProfileStringW(L"pay",keys[i],b,ini);}}
