 txt(dc,30,26,25,700,ink,L"上班赚钱器");txt(dc,30,62,14,400,muted,L"每一份努力，都在靠近想要的生活。");swprintf(b,256,L"%04d.%02d.%02d  星期%lc  %02d:%02d:%02d",t.tm_year+1900,t.tm_mon+1,t.tm_mday,L"日一二三四五六"[t.tm_wday],t.tm_hour,t.tm_min,t.tm_sec);txt(dc,30,107,16,400,muted,b);
