 card(dc,372,246,342,240,white);txt(dc,392,268,17,500,muted,L"我的心愿");if(price>0){double got=accumulated(goalstart,now,s),left=fmax(0,price-got),progress=clamp(got/price,0,1);clipped(dc,392,309,296,23,ink,wish);swprintf(b,256,L"¥ %.2f / %.2f",fmin(got,price),price);clipped(dc,392,348,296,18,blue,b);box(dc,392,385,298,7,RGB(233,236,246));box(dc,392,385,(int)(298*progress),7,blue);if(left<=0.000001){txt(dc,392,410,19,600,blue,L"心愿达成！你已经赚够啦");txt(dc,392,447,14,400,muted,L"可以为下一个心愿继续努力了。");}else{time_t eta=cached_eta();if(eta){struct tm e=local_copy(eta);swprintf(b,256,L"预计 %04d/%02d/%02d %02d:%02d 赚够",e.tm_year+1900,e.tm_mon+1,e.tm_mday,e.tm_hour,e.tm_min);txt(dc,392,410,16,600,blue,b);}else txt(dc,392,410,15,500,blue,L"目标超过 100 年估算范围");swprintf(b,256,L"还差 ¥ %.2f · 已完成 %.1f%%",left,progress*100);clipped(dc,392,447,296,14,muted,b);}}else{txt(dc,392,318,24,600,ink,L"下一个心动，是什么？");txt(dc,392,366,16,400,muted,L"填上物品和价格，就能看到");txt(dc,392,394,16,400,muted,L"努力多久可以把它带回家。");txt(dc,392,446,14,400,blue,L"点击「设置心愿」开始");}
